## tache_3b — Compter jusqu'à N

```javascript
function compterJusqua(n) {
    if (n < 1) return [];
    const result = [];
    for (let i = 1; i <= n; i++) {
        result.push(i);
    }
    return result;
}
```

## tache_3c — Remplacer lettre

```javascript
function remplacerLettre(mot, ancienne, nouvelle) {
    // Utilise split/join pour remplacer toutes les occurrences
    return mot.split(ancienne).join(nouvelle);
}
```

## tache_3d — Somme tableau

```javascript
function sommeTableau(tableau) {
    if (!Array.isArray(tableau) || tableau.length === 0) return 0;
    return tableau.reduce((sum, num) => sum + (Number(num) || 0), 0);
}
```

## tache_3e — Contient 'a'

```javascript
function contientA(mot) {
    const lowerMot = mot.toLowerCase();
    return lowerMot.includes('a');
}
```

## algo_facile_1 — Parenthèses valides

```javascript
function validerParentheses(s) {
    let balance = 0;
    for (const char of s) {
        if (char === '(') balance++;
        else if (char === ')') balance--;
        if (balance < 0) return false; // Plus de '(' que de ')'
    }
    return balance === 0; // Équilibre parfait
}
```

## algo_facile_2 — Fibonacci

```javascript
function fibonacci(n) {
    if (n <= 1) return n;
    let a = 0, b = 1;
    for (let i = 2; i <= n; i++) {
        const temp = a + b;
        a = b;
        b = temp;
    }
    return b;
}
```

## algo_moyen_1 — Mots uniques

```javascript
function motsUniques(s) {
    if (!s || typeof s !== 'string') return 0;
    // Séparation par tous les espaces (y compris multiples)
    const words = s.split(/\s+/).filter(w => w.length > 0);
    return new Set(words).size;
}
```

## algo_difficile_1 — Aplatir un tableau

```javascript
function aplatirTableau(tab) {
    // flat(1) aplatit d'un seul niveau les tableaux imbriqués
    return tab.flat(1);
}
```

## algo_defi — Rotation à droite

```javascript
function rotationDroite(tab, k) {
    if (k === 0 || !Array.isArray(tab)) return tab;
    const n = tab.length;
    // On ramène k dans l'intervalle [0, n)
    k = k % n;
    // Les k derniers éléments deviennent les premiers
    return [...tab.slice(-k), ...tab.slice(0, -k)];
}
```

